const mine = 'reviewing-' + $execution.id + '-';
// Two simultaneous clicks both pass the status check above; only the
// run whose marker survives the read-back may cause side effects.
const status = ($json && $json.status) ? String($json.status) : '';
return [{ json: { ok: status.indexOf(mine) === 0 ? 'yes' : 'no',
                  message: 'This submission was already resolved.' } }];

