const row = $('get submission row').first().json;
let review = {};
try { review = JSON.parse(row.review || '{}'); } catch (e) { review = {}; }

// The id comes from the row, never from anything the requester sent: the token
// was minted against this node and no other.
const id = (row.node_id || '').toString();
const suffix = Date.now().toString(36) + '-' + $execution.id;
return [{ json: {
  ok: id ? 'yes' : 'no',
  id,
  branchName: 'removal/' + id + '-' + suffix,
  commitMsg: 'Remove ring entry: ' + id,
  reason: (review.reason || '').toString()
} }];

const res = $json;
const status = Number(res.statusCode || 0);
const prep = $('approve: removal prep').first().json;
if (status === 404) {
  // Already gone. Nothing to remove and nothing wrong: treat it as done rather
  // than failing a request whose desired end state already holds.
  return [{ json: Object.assign({ ok: 'gone' }, prep) }];
}
if (status < 200 || status >= 300) return [{ json: Object.assign({ ok: 'no' }, prep) }];
let sha = null;
try {
  const payload = typeof res.data === 'string' ? JSON.parse(res.data) : res.data;
  sha = payload.sha || null;
} catch (e) { sha = null; }
return [{ json: Object.assign({ ok: sha ? 'yes' : 'no', existingSha: sha }, prep) }];

const res = $json;
const status = Number(res.statusCode || 0);
if (status < 200 || status >= 300) return [{ json: { ok: 'no' } }];
try {
  const payload = typeof res.data === 'string' ? JSON.parse(res.data) : res.data;
  const ring = JSON.parse(Buffer.from(payload.content || '', 'base64').toString('utf-8'));
  if (!Array.isArray(ring)) return [{ json: { ok: 'no' } }];
  return [{ json: { ok: 'yes', ring, sha: payload.sha } }];
} catch (e) {
  // A swallowed failure here silently disables both the id-collision check and
  // creator_id matching, so it is reported rather than defaulted to [].
  return [{ json: { ok: 'no' } }];
}

const row = $('get submission row').first().json;
const ring = $json.ring;
let entry = {};
try { entry = JSON.parse(row.entry || '{}'); } catch (e) { entry = {}; }

/**
 * Entry id generation.
 *
 * The schema requires `id` and constrains it to `^[a-z0-9]+(-[a-z0-9]+)*$`.
 * `submission-form-spec.md` section 2.1 states that it is generated at
 * approval time and is never a form field, because uniqueness is a property
 * of `ring.json` *as it exists at merge time*, and the file can gain entries
 * between someone starting a draft and a maintainer approving it.
 *
 * So the authoritative generation happens in the submission workflow, not
 * here. This module exists because the same rule has to be applied in two
 * places and disagreeing about it would be worse than duplicating it: the
 * form shows the submitter a preview of the id their entry will get, and the
 * workflow computes the real one against the live file. Keeping the shape in
 * one tested module is what lets the preview be honest.
 *
 * The preview is labelled as provisional in the UI for exactly the reason
 * above: it is computed against the ring as the submitter's browser last saw
 * it, and the real one is computed later against the merged file.
 */

/** Leaves room for a `-10`-scale suffix inside a sane total length. */
const MAX_BASE_LENGTH = 48;

/**
 * Reduces arbitrary text to the schema's id alphabet.
 *
 * Unicode is normalized to NFKD and combining marks are stripped first, so
 * accented Latin degrades to its base letters ("Café" to "cafe") rather than
 * having those characters dropped outright. That matters here: creator names
 * are the main input to this function and mangling them is a bad first
 * impression, but the schema's pattern is ASCII-only and this is the last
 * point where anything can be done about it.
 *
 * Scripts with no Latin decomposition (Cyrillic, Han, Arabic) reduce to
 * nothing, which is why {@link entrySlug} has a fallback and does not assume
 * this returns a non-empty string. Transliterating them properly needs a
 * library per script and is not worth it for a field nobody reads: the id is
 * a URL-safe key, and `creator` carries the actual name everywhere it is
 * displayed.
 * @param {string} value
 * @returns {string}
 */
function slugify(value) {
	return (
		(value ?? '')
			.normalize('NFKD')
			// Combining diacritical marks, written as escapes rather than literal
			// characters so the rule survives any editor or tool that would
			// normalize this file's own bytes back into composed form.
			.replace(/[\u0300-\u036f]/g, '')
			.toLowerCase()
			.replace(/[^a-z0-9]+/g, '-')
			.replace(/^-+|-+$/g, '')
	);
}

/**
 * The base id for an entry, before any collision suffix.
 *
 * Composed as type-creator so ids sort into type groups and stay readable in
 * a diff, which is the one place a human actually looks at them: the pull
 * request that adds the entry to `ring.json`. There is no work-level title to
 * fold in here any more (a node represents a creator, not a single work, per
 * the Creator Nodes addendum), so two nodes of the same type from the same
 * creator collide on this base and rely entirely on {@link uniqueEntryId}'s
 * suffix, which is exactly the case that mechanism exists for (a creator's
 * two linked nodes, capped at that same count for the same reason).
 *
 * Truncation cuts at a hyphen where one is close enough to the limit, rather
 * than mid-word, so a truncated id still reads as words. If nothing suitable
 * is near the cut, it takes the hard truncation and strips any trailing
 * hyphen, since a trailing hyphen would violate the schema's pattern.
 * @param {{ type?: string, creator?: string }} entry
 * @returns {string}
 */
function entrySlug(entry) {
	const base = [entry?.type, entry?.creator]
		.map((part) => slugify(String(part ?? '')))
		.filter(Boolean)
		.join('-');

	// Every part was empty or non-Latin. Callers must still get a valid id.
	if (!base) return 'entry';

	if (base.length <= MAX_BASE_LENGTH) return base;

	const cut = base.slice(0, MAX_BASE_LENGTH);
	const lastHyphen = cut.lastIndexOf('-');
	const trimmed = lastHyphen > MAX_BASE_LENGTH - 12 ? cut.slice(0, lastHyphen) : cut;
	return trimmed.replace(/-+$/, '') || 'entry';
}

/**
 * The final id, given the ids already in the ring.
 *
 * Suffixes start at `-2` rather than `-1`, so the first duplicate reads as
 * "the second one of these" instead of implying the original was `-1`.
 *
 * Takes the existing ids as an argument rather than reading `ring.json`
 * itself, because the two callers get that list from completely different
 * places (the browser's already-loaded ring store; the workflow's fetch of
 * the file at merge time) and neither should be reimplemented inside the
 * other.
 * @param {{ type?: string, creator?: string }} entry
 * @param {Iterable<string>} existingIds
 * @returns {string}
 */
function uniqueEntryId(entry, existingIds = []) {
	const taken = new Set(existingIds);
	const base = entrySlug(entry);
	if (!taken.has(base)) return base;

	let n = 2;
	while (taken.has(`${base}-${n}`)) n++;
	return `${base}-${n}`;
}

let id;
if (row.node_id) {
  // An update or removal acts on an existing entry; its id is not re-derived.
  id = row.node_id;
} else {
  const taken = new Set(ring.map((e) => e && e.id));

  // The id the form showed the submitter, and the one their generated site
  // already carries in its footer. Honoured when it is still free, so the
  // embed a creator has already published keeps matching. It is read from the
  // stored entry rather than trusted from the request: the row was written at
  // submit time and cannot be edited afterwards.
  //
  // Validated against the schema's own pattern before use -- this arrives as
  // submitter-influenced data, and an id is written into a file path and a
  // branch name downstream.
  const requested = (entry.requested_id || '').toString();
  const valid = /^[a-z0-9]+(-[a-z0-9]+)*$/.test(requested) && requested.length <= 64;

  if (valid && !taken.has(requested)) {
    id = requested;
  } else {
    // Free-standing collision, or no usable request: fall back to deriving it
    // the same way the browser would have. uniqueEntryId's suffix settles the
    // rest, and the creator's embed is then stale -- which the health check
    // now reports as ring_widget_site_id_unmatched rather than as a missing
    // embed, and /update is the repair path.
    id = uniqueEntryId({ type: entry.type, creator: entry.creator }, taken);
  }
}

// Host comparison, done by hand: `URL` is not defined in the n8n Code sandbox.
// The original used `new URL()` inside a try/catch, so it threw ReferenceError
// on every run and the catch swallowed it -- creator_id was never once
// assigned. A silent failure, invisible in the response and the execution log.
const hostOf = (u) => {
  const m = (u || '').toString().match(/^[A-Za-z][A-Za-z0-9+.-]*:\/\/([^\/?#]*)/);
  if (!m) return '';
  let h = m[1];
  if (h.indexOf('@') !== -1) h = h.split('@').pop();
  if (h.charAt(0) === '[') return h.slice(1, h.indexOf(']')).toLowerCase();
  return h.split(':')[0].toLowerCase();
};

let creator_id = null;
const host = hostOf(row.source_url);
if (host) {
  const match = ring.find((e) => e && hostOf(e.source_url) === host && e.creator_id);
  if (match) creator_id = match.creator_id;
}

return [{ json: { id, creator_id, ring: $json.ring, sha: $json.sha } }];

const row = $('get submission row').first().json;
let entry = {};
try { entry = JSON.parse(row.entry || '{}'); } catch (e) { entry = {}; }
const gen = $json;

// Explicit allowlist, matching toRingEntry in src/lib/submissionValidation.js
// field for field. Never a denylist: a field added to the form later must be
// deliberately published, not published by default.
const allowed = ['creator', 'type', 'why', 'tags', 'tracks', 'pages', 'artworks',
                 'excerpts', 'thumb_url', 'thumb_position', 'preview_url', 'trailer_url', 'explicit'];
const out = { id: gen.id };
for (const k of allowed) if (entry[k] !== undefined) out[k] = entry[k];

// Backend-assigned. verification_token is a REQUIRED public field per
// schema/ring.schema.json -- it is the token that must stay in the member's
// meta tag, not a leak.
out.source_url = row.source_url;
out.verification_token = row.verification_token;
if (gen.creator_id) out.creator_id = gen.creator_id;

// n8n's Code sandbox cannot import the repository's Prettier dependency, but
// every generated member file is checked by `prettier --check .`. This small
// JSON-only renderer mirrors the relevant Prettier settings: tabs, a 100-column
// width, multiline objects/object arrays, and compact scalar arrays when they
// fit. Normalizing through JSON first preserves JSON.stringify's treatment of
// undefined values without teaching a formatter about non-JSON JavaScript.
const canonical = JSON.parse(JSON.stringify(out));
const WIDTH = 100;
const TAB_WIDTH = 2;
const tabs = (n) => '\t'.repeat(n);
const scalar = (v) => v === null || typeof v !== 'object';
const renderJson = (value, depth, column) => {
  if (scalar(value)) return JSON.stringify(value);

  if (Array.isArray(value)) {
    if (!value.length) return '[]';
